    "id": "81000000-0000-0000-0000-000000000004",
    "title": "Designing buildings for summer comfort",
    "transcript": "Today's lecture considers passive cooling. The term describes strategies that reduce heat without relying primarily on powered refrigeration. The first principle is shading. External shades stop sunlight before it passes through glass and are often more effective than internal blinds. Orientation matters: low afternoon sun can make west-facing windows particularly difficult to shade. A second strategy is ventilation. Cross ventilation needs openings on different sides of a room and a path for air to move between them. Opening one small window does not guarantee useful airflow. Night ventilation can cool exposed concrete or brick when outside temperatures fall. These heavy materials provide thermal mass, absorbing heat during the day and releasing it later. However, the approach works poorly when nights remain hot. Insulation slows heat transfer, but it cannot remove heat already trapped indoors. Designers must therefore consider shading, ventilation and insulation together. Roof colour also matters. Light-coloured surfaces reflect more sunlight than dark ones, although glare and local conditions should be considered. In humid climates, comfort may depend on air movement as much as air temperature. Ceiling fans can help people feel cooler without reducing the room temperature. Finally, occupants need clear controls. A design that depends on opening windows at the right time may fail if users cannot understand or safely operate them. Buildings should be evaluated after occupation, using both measurements and feedback from residents.",
