    "id": "81000000-0000-0000-0000-000000000026",
    "title": "Coastal walk · Welcome briefing 3",
    "transcript": "Welcome to our coastal walk. Before we begin, I will explain the arrangements. The weekly meeting day is Tuesday; please ignore the Saturday date on the earlier leaflet. The first meeting will be on 10 November, and the session itself starts at 10:15. The total fee is 39 pounds, including the basic materials.\nOur meeting venue is the Visitor Centre. Use room 122, not the main hall. There is space for 15 participants, and staff need to keep a clear route to the entrance. The programme will run for 4 weeks. Our leader is Morgan. Please bring walking boots; the centre will provide the remaining equipment.\nAt the first meeting, everyone will complete a short introduction and discuss what they hope to learn. You will then work in pairs before moving on to a small individual activity. Beginners are welcome, so do not feel that you must prepare an impressive project in advance.\nIf you are delayed, enter quietly and speak to the assistant. Do not interrupt someone who is giving instructions. If you need to leave early, tell the leader before the session starts. We will distribute feedback forms at the end of the programme. Please describe specific examples of what helped you, rather than simply ticking every box. Your comments will influence the next programme.",
