    "title": "Pottery workshop · Booking details 5",
    "transcript": "Receptionist: Good morning. How can I help?\nCaller: I am interested in the pottery workshop. Is it still on Saturday?\nReceptionist: That was the old arrangement. It now meets on Monday, starting on 10 November.\nCaller: I saw two times on the notice.\nReceptionist: Doors open earlier, but the actual starting time is 9:30. Please arrive a little beforehand so registration does not delay the session.\nCaller: Does the fee include materials?\nReceptionist: Yes. The complete fee is 58 pounds. You will not be asked to pay separately for the basic materials.\nCaller: Where should I go?\nReceptionist: We meet at the Arts Centre, in room 141. Ask at reception if you cannot find it; another group may be using the main hall.\nCaller: Is it a large group?\nReceptionist: We accept a maximum of 16 participants. That gives the leader time to help everyone. The programme lasts 3 weeks.\nCaller: Who is teaching it?\nReceptionist: The leader’s surname is Chen. Bring clay tools. Everything else will be provided.\nCaller: Can I send someone else if I am unable to attend?\nReceptionist: Please contact us first. We keep a waiting list, so places cannot simply be transferred. You may cancel before the first session, but tell us as early as possible.\nCaller: Thank you. I will check my schedule and complete the registration form.",
