    "id": "81000000-0000-0000-0000-000000000071",
    "title": "Cycle training · Project tutorial 7",
    "transcript": "Student: We need to organise the practical element of our cycle training study.\nTutor: First, confirm the arrangements so the information sheet is accurate.\nStudent: The group meets on Tuesday. We originally considered Saturday, but that would exclude some participants. We will begin on 17 November at 10:15.\nTutor: What will participants pay?\nStudent: The fee is 84 pounds. We should state that this includes basic materials, otherwise people may budget twice.\nTutor: And where will it take place?\nStudent: At the Sports Centre, room 167. The maximum group size is 15. We agreed on 5 weeks so we can observe more than a single session.\nTutor: Who is responsible for the sessions?\nStudent: The leader is Walker. The equipment list asks participants to bring a helmet.\nTutor: Now think about your research question. Attendance alone will not tell you whether people learned anything.\nStudent: We could compare a short task at the beginning and end.\nTutor: That might help, but make the task comparable. A much easier final task would exaggerate improvement.\nStudent: Should we interview everyone?\nTutor: That would be valuable, but you have limited time. Explain how you select interviewees and record who declines. Do not claim your interviews represent people you never spoke to.\nStudent: I will revise the plan and add those limitations to the presentation.",
    "audioUrl": null,
    "sectionNumber": 3,
    "turns": [
      {
        "speaker": "Student",
        "text": "We need to organise the practical element of our cycle training study."
      },
      {
        "speaker": "Tutor",
        "text": "First, confirm the arrangements so the information sheet is accurate."
      },
      {
        "speaker": "Student",
        "text": "The group meets on Tuesday. We originally considered Saturday, but that would exclude some participants. We will begin on 17 November at 10:15."
      },
      {
        "speaker": "Tutor",
        "text": "What will participants pay?"
      },
      {
        "speaker": "Student",
        "text": "The fee is 84 pounds. We should state that this includes basic materials, otherwise people may budget twice."
      },
      {
        "speaker": "Tutor",
        "text": "And where will it take place?"
      },
      {
        "speaker": "Student",
        "text": "At the Sports Centre, room 167. The maximum group size is 15. We agreed on 5 weeks so we can observe more than a single session."
      },
      {
        "speaker": "Tutor",
        "text": "Who is responsible for the sessions?"
      },
      {
        "speaker": "Student",
        "text": "The leader is Walker. The equipment list asks participants to bring a helmet."
      },
      {
        "speaker": "Tutor",
        "text": "Now think about your research question. Attendance alone will not tell you whether people learned anything."
      },
      {
        "speaker": "Student",
        "text": "We could compare a short task at the beginning and end."
      },
      {
        "speaker": "Tutor",
        "text": "That might help, but make the task comparable. A much easier final task would exaggerate improvement."
      },
      {
        "speaker": "Student",
        "text": "Should we interview everyone?"
      },
      {
        "speaker": "Tutor",
        "text": "That would be valuable, but you have limited time. Explain how you select interviewees and record who declines. Do not claim your interviews represent people you never spoke to."
      },
      {
        "speaker": "Student",
        "text": "I will revise the plan and add those limitations to the presentation."
      }
    ],
    "speakerPersonas": {
      "Tutor": "male academic tutor speaking with a measured, authoritative pace",
      "Student": "female university student speaking naturally, engaged and articulate"
    }
